'use strict';
const design = require('./receipt-design');
const QRCode = require('qrcode');

// QR images are generated by the server; a client cannot save an unrelated
// picture under a QR payload. Encoding text never fetches the supplied address.
async function resolveReceiptDesign(value) {
  const result = design.normalize(value);
  const cache = new Map();
  for (const layout of Object.values(result.layouts)) {
    for (const block of layout.blocks) {
      if (block.type !== 'qr') continue;
      if (!cache.has(block.text)) {
        cache.set(
          block.text,
          await QRCode.toDataURL(block.text, {
            width: 384,
            margin: 4,
            errorCorrectionLevel: 'M',
          })
        );
      }
      block.src = cache.get(block.text);
    }
  }
  return result;
}
module.exports = { resolveReceiptDesign };
